def analyze(datasets):
    def pick(cols):
        return next((d for d in datasets if all(c in d.get('columns', []) for c in cols)), None)
    trend = pick(['reporting_period', 'confirmed_revenue', 'confirmed_units'])
    sep = pick(['product_name', 'sku', 'total_quantity', 'total_amount'])
    aug = next((d for d in datasets if d.get('id') == 'q5'), None)
    out = []
    if trend:
        rows = trend['rows']
        rev = [r['confirmed_revenue'] for r in rows]
        units = [r['confirmed_units'] for r in rows]
        latest, prev = rows[0], rows[1]
        out.append({'title': '销售额与销量趋势', 'detail': '最近六个报告期已确认销售额从 %.2f 到 %.2f，9月环比 %.2f%%；销量9月 %.0f 箱，环比 %.2f%%。' % (rev[-1], rev[0], (latest['confirmed_revenue']/prev['confirmed_revenue']-1)*100, latest['confirmed_units'], (latest['confirmed_units']/prev['confirmed_units']-1)*100), 'evidence': {'periods': len(rows), 'sep_revenue': latest['confirmed_revenue'], 'aug_revenue': prev['confirmed_revenue'], 'sep_units': latest['confirmed_units'], 'aug_units': prev['confirmed_units'], 'avg_revenue': round(sum(rev)/len(rev), 2)}})
    if sep:
        rows = sorted(sep['rows'], key=lambda r: r['total_amount'], reverse=True)
        top = rows[0]
        total_amt = sum(r['total_amount'] for r in rows)
        total_qty = sum(r['total_quantity'] for r in rows)
        out.append({'title': '9月畅销产品', 'detail': '9月采购金额最高的是 %s（%s），%.2f 元、%d 箱，占当月采购额 %.1f%%；当月共 %d 个SKU、%d 箱、%.2f 元。' % (top['product_name'], top['sku'], top['total_amount'], top['total_quantity'], top['total_amount']/total_amt*100, len(rows), total_qty, total_amt), 'evidence': {'sku_count': len(rows), 'total_amount': round(total_amt, 2), 'total_quantity': total_qty, 'top_sku': top['sku'], 'top_amount': top['total_amount']}})
    if sep and aug:
        cur = {r['sku']: r for r in sep['rows']}
        old = {r['sku']: r for r in aug['rows']}
        big = max(cur, key=lambda k: cur[k]['total_amount'] - old.get(k, {}).get('total_amount', 0))
        c, o = cur[big], old.get(big, {})
        out.append({'title': '环比增长最快产品', 'detail': '%s（%s）采购金额由8月 %.2f 元升至9月 %.2f 元，增加 %.2f 元；箱数由 %d 增至 %d。' % (c['product_name'], c['sku'], o.get('total_amount', 0), c['total_amount'], c['total_amount']-o.get('total_amount', 0), o.get('total_quantity', 0), c['total_quantity']), 'evidence': {'sku': c['sku'], 'sep_amount': c['total_amount'], 'aug_amount': o.get('total_amount', 0), 'delta': round(c['total_amount']-o.get('total_amount', 0), 2)}})
    return out
